'use strict';
(() => {
  const e=escapeHTML;
  const labels={external_or_interrupted:'Boshqa jarayon yoki uzilgan skan',queued:'Navbatda',running:'Tekshirilmoqda',completed:'Belgilangan qamrovda tugadi',partial:'Tugadi · qamrov to‘liq emas',failed:'Tekshiruv bajarilmadi',no_supported_packages:'Qo‘llanadigan aniq versiya topilmadi',cancelled:'Bekor qilindi'};
  const owaspBadges=tags=>(tags||[]).map(o=>`<span class="badge neutral" title="${e(o.name)}">${e(o.code)}</span>`).join(' ');
  const verifiedBadge=f=>f.verified?'<span class="badge green">Dalil bilan tasdiqlangan</span>':'<span class="badge amber">Qo‘lda tekshirish kerak</span>';
  const reviewNames={investigating:'Tekshirilmoqda',fix_planned:'Tuzatish rejalashtirilgan',accepted_risk:'Xavf qabul qilingan',false_positive:'Noto‘g‘ri signal'};
  const reasons={unsupported_manifest:'Bu manifest formati hali qo‘llanmaydi',npm_lockfile_missing:'npm lock fayli yo‘q',python_not_exact_pin_or_unsupported_directive:'Python aniq == versiya emas yoki qo‘llanmaydigan ko‘rsatma',go_replace_or_exclude_requires_resolved_inventory:'Go replace/exclude uchun yakuniy inventar kerak',manifest_over_16mb:'Manifest 16 MB dan katta',invalid_manifest:'Manifest o‘qilmadi',npm_version_unresolved:'npm versiyasi aniq emas',npm_workspace_link_unresolved:'Workspace havolasi hal qilinmagan',python_pyproject_not_exact_pin:'pyproject.toml’da aniq == versiya emas (diapazon yoki marker)',python_pyproject_no_dependencies:'pyproject.toml’da [project] bog‘liqliklari yo‘q',toml_unreadable:'TOML fayli o‘qilmadi',gradle_lockfile_missing:'Gradle: aniq versiyalar yo‘q (./gradlew dependencies --write-locks yoki ./gradlew dependencies > gradle-dependencies.txt)',maven_lockfile_missing:'Maven: aniq versiyalar yo‘q (mvn dependency:tree -DoutputFile=dependency-tree.txt)',yarn_non_registry_source:'yarn.lock: registry bo‘lmagan manba (git, fayl, workspace)',yarn_version_unresolved:'yarn.lock: aniq versiya o‘qilmadi',pnpm_non_registry_source:'pnpm-lock: registry bo‘lmagan manba (tarball, git, papka)',pnpm_version_unresolved:'pnpm-lock: aniq versiya o‘qilmadi',nuget_lockfile_missing:'NuGet: packages.lock.json yo‘q (<RestorePackagesWithLockFile>true</RestorePackagesWithLockFile>, keyin dotnet restore)',nuget_entry_unresolved:'packages.lock.json: aniq versiya o‘qilmadi',maven_tree_entry_unresolved:'Maven daraxti: koordinata o‘qilmadi',gradle_tree_entry_unresolved:'Gradle daraxti: aniq versiya o‘qilmadi',toml_lock_needs_python_311:'TOML o‘qish uchun Python 3.11+ kerak',linked_directory_skipped:'Symlink papka o‘tkazib yuborildi',linked_manifest_skipped:'Symlink manifest o‘tkazib yuborildi'};
  let report=null,reviewData={},job=null,page=0,filter='',priority='all';
  function results(){
    if(!report)return;
    const matched=(report.findings||[]).filter(f=>(priority==='all'||f.priority===priority)&&JSON.stringify([f.package,f.aliases,f.summary]).toLowerCase().includes(filter));
    page=Math.min(page,Math.max(0,Math.ceil(matched.length/25)-1));
    $('dep-findings').innerHTML=matched.slice(page*25,page*25+25).map(f=>{
      const r=reviewData[f.id];
      const epss=f.epss?`${(f.epss.epss*100).toFixed(1)}% ekspluatatsiya ehtimoli (EPSS, ${(f.epss.percentile*100).toFixed(0)}-persentil)`:'EPSS ma’lumoti yo‘q';
      return `<details class="repo-finding"><summary><span class="badge ${f.priority==='P1'?'red':f.priority==='P2'?'amber':'neutral'}">${e(f.priority)}</span><strong>${e(f.package.name)} <small>${e(f.package.version)}</small></strong><span>${e(f.advisory_id)}</span></summary><div class="finding-body"><p>${e(f.summary)}</p><p><strong>${e(f.severity)}</strong> · ${e(f.package.ecosystem)} · ${e(f.priority_reason)}</p><p>${e((f.cwe_ids||[]).join(', ')||'CWE aniqlanmagan')} ${owaspBadges(f.owasp_top10_2025)} ${verifiedBadge(f)}</p><p>${e(epss)}</p><p>${f.known_exploited===true?'CISA KEV: amalda ekspluatatsiya qilingani ma’lum.':f.known_exploited===false?'CISA KEV ro‘yxatida yo‘q; bu xavfsizlik tasdig‘i emas.':'CISA KEV ma’lumoti olinmagan.'}</p><p class="remediation">${e(f.remediation)}<br>Tuzatilgan versiyalar: <strong>${e(f.fixed_versions.join(', ')||'Manbada ko‘rsatilmagan')}</strong></p><div class="repo-evidence">${f.occurrences.map(o=>`<div><span>MANBA</span><div><p>${e(o.manifest)}</p><small>${e(o.locator)} · ${e(o.scope)}</small></div></div>`).join('')}</div><p>Bevosita mos yozuvlar: ${e((f.matched_advisory_ids||[]).join(', ')||'Eski hisobot; qayta skan qiling')}</p><p>Bog‘langan identifikatorlar: ${e(f.aliases.join(', '))}</p><p class="muted">${e(f.alias_note||'')}</p><p class="muted">${e(f.verification_note||'')}</p><p>${f.references.filter(url=>url.startsWith('https://osv.dev/vulnerability/')).map(url=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">OSV manbasi ↗</a>`).join(' · ')}</p>${r?`<p class="baseline-note">${e(reviewNames[r.status])} · ${e(r.owner)} · ${e(r.note)}</p>`:''}<form class="review-form" data-dep-review="${e(f.id)}"><label>Qaror<select name="status">${Object.entries(reviewNames).map(([key,value])=>`<option value="${key}" ${r?.status===key?'selected':''}>${value}</option>`).join('')}</select></label><label>Mas’ul<input name="owner" required maxlength="120" value="${e(r?.owner||'')}"></label><label class="review-note">Asos<textarea name="note" required maxlength="1000">${e(r?.note||'')}</textarea></label><button class="secondary" type="submit">Qarorni saqlash</button><span class="review-feedback" role="status"></span></form></div></details>`;
    }).join('')||'<p class="empty">Tanlangan filtrda topilma yo‘q. Tekshiruv holati va qamrovni ham tekshiring.</p>';
    $('dep-page').textContent=`${matched.length} ta topilma · ${page+1}/${Math.max(1,Math.ceil(matched.length/25))} sahifa`;
    $('dep-prev').disabled=page===0;$('dep-next').disabled=(page+1)*25>=matched.length;
    $('dep-findings').querySelectorAll('[data-dep-review]').forEach(form=>form.addEventListener('submit',async event=>{
      event.preventDefault();const fields=new FormData(form);const button=form.querySelector('button');button.disabled=true;
      try{const saved=await api('/api/dependencies/review',{report_id:report.id,finding_id:form.dataset.depReview,status:fields.get('status'),owner:fields.get('owner'),note:fields.get('note')});reviewData[form.dataset.depReview]=saved;form.querySelector('.review-feedback').textContent='Ushbu hisobot uchun saqlandi';}catch(error){showError(error);}finally{button.disabled=false;}
    }));
  }
  function render(value){
    report=value;const c=report.coverage||{},feeds=report.feeds||{},base='/api/dependencies/reports/'+encodeURIComponent(report.id);
    $('dep-result').className='';
    const unchecked=(report.query_errors||[]).length;
    $('dep-result').innerHTML=`<div class="scanner-summary"><strong>${e(unchecked?'Tugallanmadi · '+unchecked+' ta paket tekshirilmadi':labels[report.state]||report.state)}</strong><span>${e(report.target)} · ${e(time(report.created_at))}</span><a href="${base}/download">JSON ↓</a><a href="${base}/markdown">O‘qiladigan hisobot ↓</a>${report.inventory_sha256?`<a href="${base}/inventory">Inventar ↓</a>`:''}</div><div class="scanner-cards"><article class="scanner-card"><h3>Kutubxonalar</h3><strong>${e(c.unique_packages??'—')}</strong><p>${e(c.occurrences??0)} ta nusxa · ${e(c.manifests?.length??0)} ta manifest</p></article><article class="scanner-card"><h3>Zaiflik mosliklari</h3><strong>${e(report.count||0)}${unchecked?' +?':''}</strong><p>${unchecked?e(unchecked)+' ta paket tekshirilmadi — bu son to‘liq emas':'Amaliy ta’sirini tekshirish kerak'}</p></article><article class="scanner-card"><h3>Avval tekshiring</h3><strong>${e(report.priority_counts?.P1||0)} ta P1</strong><p>KEV yoki kritik og‘irlik bahosi</p></article><article class="scanner-card"><h3>Tasdiqlash</h3><strong>${report.verification_summary?e(report.verification_summary.confirmed_by_evidence)+' / '+e(report.verification_summary.total):e(report.count||0)+' ta (eski format)'}</strong><p>${report.verification_summary?'Dalil bilan tasdiqlangan; qolgani qo‘lda tekshiriladi':'Bu hisobot CWE/OWASP teglaridan oldin olingan. To‘liq tasniflash uchun qayta tekshiring.'}</p></article></div>${unchecked?`<p class="unknown-note">Diqqat: ${e(unchecked)} ta paket OSV bazasida tekshirilmadi (tarmoq yoki baza javob bermadi)${feeds.kev?.state&&feeds.kev.state!=='available'?' va CISA KEV ro‘yxati olinmadi':''}. “0 zaiflik” bu paketlar uchun “toza” degani emas — tarmoqni tekshirib qayta skan qiling.</p>`:''}<p id="dep-baseline" class="muted"></p><details class="pilot-help"><summary>Qamrov va baza yangiligi · ${e(c.gaps?.length||0)} ta bo‘shliq</summary><p>${e(c.scope||'Inventar hali tayyor emas')}</p><p>OSV: ${e(feeds.osv?.checked_packages??0)}/${e(feeds.osv?.requested_packages??0)} paket. Eng eski ishlatilgan javob: ${e(feeds.osv?.oldest_retrieved_at?time(feeds.osv.oldest_retrieved_at):'Mavjud emas')}. Kesh: 24 soatgacha.</p><p>CISA KEV: ${e(feeds.kev?.state||'Tekshirilmagan')}. So‘rov xatolari: ${e(report.query_errors?.length||0)}.</p><ul>${(c.gaps||[]).map(g=>`<li>${e(g.path)}${g.line?':'+e(g.line):''} — ${e(reasons[g.reason]||g.reason)}</li>`).join('')}</ul><p class="hash">Inventar SHA-256: ${e(report.inventory_sha256||'—')}</p></details><div class="dep-filters"><label>Qidirish<input id="dep-search" type="search" placeholder="Paket yoki CVE" value="${e(filter)}"></label><label>Ustuvorlik<select id="dep-priority">${['all','P1','P2','P3','REVIEW'].map(p=>`<option value="${p}" ${priority===p?'selected':''}>${p==='all'?'Barchasi':p}</option>`).join('')}</select></label></div><div id="dep-findings"></div><div class="scanner-summary"><button id="dep-prev" class="secondary">← Oldingi</button><span id="dep-page"></span><button id="dep-next" class="secondary">Keyingi →</button></div>`;
    if(!['queued','running'].includes(report.state)){fillBaseline('dependencies',report.id,'dep-baseline');showFixPlan(report.fix_plan,'dep-baseline');}
    $('dep-search').addEventListener('input',event=>{filter=event.target.value.toLowerCase();page=0;results();});
    $('dep-priority').addEventListener('change',event=>{priority=event.target.value;page=0;results();});
    $('dep-prev').addEventListener('click',()=>{page--;results();});$('dep-next').addEventListener('click',()=>{page++;results();});results();
  }
  async function loadHistory(){
    const rows=await api('/api/dependencies/reports?target='+encodeURIComponent($('dep-target').value));
    $('dep-history').innerHTML=rows.map(row=>`<button class="secondary scanner-history" data-dep-id="${e(row.id)}">${e(time(row.created_at))} · ${e(labels[row.state]||row.state)} · ${e(row.count||0)}</button>`).join('')||'<p>Bu loyiha hali tekshirilmagan.</p>';
    $('dep-before').innerHTML=rows.filter(r=>['completed','partial'].includes(r.state)).map(row=>`<option value="${e(row.id)}">${e(time(row.created_at))} · ${e(row.count)}</option>`).join('');
    $('dep-history').querySelectorAll('[data-dep-id]').forEach(button=>button.addEventListener('click',async()=>{if(job)return;try{reviewData=await api('/api/dependencies/reports/'+button.dataset.depId+'/reviews');render(await api('/api/dependencies/reports/'+button.dataset.depId));}catch(error){showError(error);}}));
    return rows;
  }
  async function follow(id){
    job=id;$('dep-scan').disabled=true;$('dep-target').disabled=true;$('dep-cancel').hidden=false;
    try{const row=await pollReport('/api/dependencies/reports/'+id,s=>{$('dep-progress').textContent=s.progress||labels[s.state];});if(row.active_here===false){row.state='external_or_interrupted';row.progress='Bu job boshqa terminalda yoki oldingi serverda boshlangan. O‘sha terminalni tekshiring; tugallanmagan natija.';}$('dep-progress').textContent=row.progress||labels[row.state];render(row);await loadHistory();}
    finally{job=null;$('dep-scan').disabled=false;$('dep-target').disabled=false;$('dep-cancel').hidden=true;}
  }
  async function init(){
    $('dep-scan').addEventListener('click',async()=>{try{reviewData={};page=0;const result=await api('/api/dependencies/scan',{target:$('dep-target').value});await follow(result.id);}catch(error){showError(error);}});
    $('dep-cancel').addEventListener('click',async()=>{try{await api('/api/dependencies/cancel',{report_id:job});$('dep-progress').textContent='Bekor qilish so‘raldi. Joriy so‘rov tugashi kutilmoqda.';}catch(error){showError(error);}});
    $('dep-target').addEventListener('change',async()=>{report=null;reviewData={};$('dep-result').className='empty';$('dep-result').textContent='Loyiha tanlandi. Tekshiruvni boshlang yoki tarixdan hisobot oching.';$('dep-delta').textContent='';await loadHistory();});
    $('dep-compare').addEventListener('click',async()=>{if(!report)return;try{const result=await api('/api/dependencies/compare',{before:$('dep-before').value,after:report.id});$('dep-delta').textContent=`Yangi ${result.added.length} · Joriy hisobotda yo‘q ${result.absent.length} · Saqlangan ${result.unchanged.length}. ${result.note}`;}catch(error){showError(error);}});
    try{const targets=await api('/api/scanners/targets');$('dep-target').innerHTML=targets.map(t=>`<option value="${e(t.id)}" ${t.available?'':'disabled'}>${e(t.name)}</option>`).join('');const rows=await loadHistory();if(rows.length){if(['queued','running'].includes(rows[0].state))follow(rows[0].id).catch(showError);else{reviewData=await api('/api/dependencies/reports/'+rows[0].id+'/reviews');render(await api('/api/dependencies/reports/'+rows[0].id));}}}catch(error){showError(error);}
  }
  whenShown(['dependencies'], init);
})();
